def sieve(max):
    if max < 2:
        return []
    is_prime = [True] * (max + 1)
    is_prime[0] = False
    is_prime[1] = False
    primes = []
    for num in range(2, max + 1):
        if is_prime[num]:
            primes.append(num)
            for multiple in range(num * num, max + 1, num):
                is_prime[multiple] = False
    return primes

def subsequences(a, b, k):
    if k == 0:
        return []

    ret = []
    for i in range(a, b + 1 - k):
        ret.extend(
            [i] + rest for rest in subsequences(i + 1, b, k - 1)
        )

    return ret

